sys_script_include.script:
var ClaudeConnector = Class.create();
ClaudeConnector.prototype = {
    initialize: function() {
        this.baseUrl    = gs.getProperty('x_146833_claudec_0.base_url',  'https://api.servicesessentials.ibm.com');
        this.authToken  = gs.getProperty('x_146833_claudec_0.auth_token', '');
        this.model      = gs.getProperty('x_146833_claudec_0.model',      'claude-sonnet-5');
        this.maxTokens  = parseInt(gs.getProperty('x_146833_claudec_0.max_tokens', '4096'), 10);
        this.messagesUrl = this.baseUrl.replace(/\/$/, '') + '/v1/messages';
    },

    /**
     * Send a chat request to the Claude API.
     * @param {Array}  messages      - Array of {role, content} objects (full conversation history)
     * @param {Object} opts          - Optional overrides: model, system_prompt, prefill, stop_sequences
     * @returns {Object}             - {success: bool, text: string, inputTokens: int, outputTokens: int, model: string, error: string}
     */
    chat: function(messages, opts) {
        opts = opts || {};

        var model        = opts.model        || this.model;
        var systemPrompt = opts.system_prompt || '';
        var prefill      = opts.prefill       || '';
        var stopSeqs     = opts.stop_sequences || [];

        // Append prefill hint to the last user message when provided
        var msgsCopy = [];
        for (var i = 0; i < messages.length; i++) {
            msgsCopy.push({ role: messages[i].role, content: messages[i].content });
        }
        if (prefill && msgsCopy.length > 0 && msgsCopy[msgsCopy.length - 1].role === 'user') {
            msgsCopy[msgsCopy.length - 1].content += '\n\nRespond starting with: ' + prefill;
        }

        var payload = {
            model:      model,
            max_tokens: this.maxTokens,
            messages:   msgsCopy
        };
        if (systemPrompt) { payload.system = systemPrompt; }
        if (stopSeqs && stopSeqs.length > 0) { payload.stop_sequences = stopSeqs; }

        var request = new sn_ws.RESTMessageV2();
        request.setEndpoint(this.messagesUrl);
        request.setHttpMethod('POST');
        request.setRequestHeader('x-api-key',          this.authToken);
        request.setRequestHeader('anthropic-version',  '2023-06-01');
        request.setRequestHeader('content-type',       'application/json');
        request.setRequestBody(JSON.stringify(payload));
        request.setHttpTimeout(120000); // 120 s

        try {
            var response   = request.execute();
            var statusCode = response.getStatusCode();
            var body       = response.getBody();

            if (statusCode < 200 || statusCode >= 300) {
                return { success: false, error: 'API error ' + statusCode + ': ' + body };
            }

            var json = JSON.parse(body);
            var text = '';
            if (json.content && json.content.length > 0) {
                for (var c = 0; c < json.content.length; c++) {
                    if (json.content[c].type === 'text') {
                        text += json.content[c].text;
                    }
                }
            }
            var usage       = json.usage || {};
            var inputTokens = usage.input_tokens  || 0;
            var outTokens   = usage.output_tokens || 0;
            var modelUsed   = json.model || model;

            return {
                success:      true,
                text:         text,
                inputTokens:  inputTokens,
                outputTokens: outTokens,
                model:        modelUsed
            };
        } catch (e) {
            return { success: false, error: e.toString() };
        }
    },

    type: 'ClaudeConnector'
};
